SELECT id
FROM orders
WHERE status = 'STOCK_RESERVED'
  AND updated_at < DATE_SUB(NOW(6), INTERVAL #{thresholdMinutes} MINUTE)
  AND is_deleted = false
  AND id > #{lastId}

  AND updated_at >= #{startDate}


  AND updated_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)

ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE stock
SET reserved_quantity = reserved_quantity - #{quantity}, updated_at = NOW(6)
WHERE product_id = #{productId}
  AND reserved_quantity >= #{quantity}
